def verify_source(source):
    source=Path(source)
    dispatch_only={'assembly_suite_on_rosie.sh','assembly_review_on_rosie.sh','DISPATCH-PROVENANCE.json','snapshot-sha256.json'}
    changed=[]
    for name,expected in json.loads((source/'telemetry-parent-sha256.json').read_text()).items():
        if digest(source/name)!=expected:
            assert name in dispatch_only,name;changed.append(name)
    if changed:
        provenance=json.loads((source/'DISPATCH-PROVENANCE.json').read_text())
        assert provenance['candidate_contract_sha256']==digest(source/'CONTACT-TRACE-CANDIDATE-CONTRACT.json')
        assert provenance['runtime']=='contact_trace_lid_precontact_trial.py' and provenance['acquisition_checker']=='check_contact_trace_lid_precontact.py'
        for name,expected in json.loads((source/'snapshot-sha256.json').read_text()).items():assert digest(source/name)==expected,name
    original=(source/'multistart_lid_precontact_trial.py').read_text();child=(source/'contact_trace_lid_precontact_trial.py').read_text()
    for a,b in reversed(json.loads((source/'contact-trace-runtime-patches.json').read_text())):
        assert child.count(b)==1;child=child.replace(b,a)
    assert child==original,'Telemetry patches do not recover exact parent runtime'
    return digest(source/'contact_trace_lid_precontact_trial.py')

